select case when units >= 40 then 'high' when units >= 9 then 'mid' else 'low' end as units_bucket, sum(units) as total_units, count(*) as cnt, sum(sum(units)) over (order by case when units >= 40 then 'high' when units >= 9 then 'mid' else 'low' end) as cumulative_units from store_sales where units < 34 group by case when units >= 40 then 'high' when units >= 9 then 'mid' else 'low' end;
